"""Error contract (RFC 9457 ``application/problem+json``) for every non-2xx API response.

Rules (docs/api-contract.md s3):
* ``code`` is a stable machine-readable identifier from :class:`ErrorCode`.
* ``detail`` is a fixed human string per code; it NEVER echoes user input.
* ``request_id`` is generated by the server; a client-supplied id is never reused.
* A 404 for "not visible" is byte-identical (except ``request_id``) whether the object
  does not exist or exists but is hidden from the caller.
"""

from __future__ import annotations

from enum import StrEnum
from typing import Final
from uuid import UUID

from pydantic import BaseModel, ConfigDict, Field

PROBLEM_MEDIA_TYPE: Final = "application/problem+json"
ERROR_TYPE_PREFIX: Final = "urn:tenantlab:error:"
MAX_FIELD_ERRORS: Final = 20


class ErrorCode(StrEnum):
    """Closed set of error codes. Adding one is an API change (see docs/api-contract.md)."""

    AUTH_TOKEN_INVALID = "auth.token_invalid"  # noqa: S105 - an error-code identifier, not a secret
    AUTH_PRINCIPAL_DISABLED = "auth.principal_disabled"
    RESOURCE_NOT_FOUND = "resource.not_found"
    TENANT_SUSPENDED = "tenant.suspended"
    AUTHZ_FORBIDDEN = "authz.forbidden"
    AUTHZ_MARKET_DENIED = "authz.market_denied"
    REQUEST_INVALID = "request.invalid"
    REQUEST_TOO_LARGE = "request.too_large"
    CONFLICT_STALE_REVISION = "conflict.stale_revision"
    CONFLICT_LAST_OWNER = "conflict.last_owner"
    QUOTA_EXCEEDED = "quota.exceeded"
    SERVICE_UNAVAILABLE = "service.unavailable"
    INTERNAL_ERROR = "internal.error"


class FieldError(BaseModel):
    """One validation problem. Location and a machine code only; never the offending value."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    loc: tuple[str | int, ...] = Field(max_length=8)
    code: str = Field(min_length=1, max_length=64, pattern=r"^[a-z0-9_.]+$")


class ProblemDetail(BaseModel):
    """Body of every error response."""

    model_config = ConfigDict(extra="forbid", frozen=True)

    type: str = Field(pattern=r"^urn:tenantlab:error:[a-z_]+\.[a-z_]+$")
    title: str = Field(min_length=1, max_length=80)
    status: int = Field(ge=400, le=599)
    code: ErrorCode
    detail: str = Field(min_length=1, max_length=200)
    request_id: UUID
    errors: tuple[FieldError, ...] = Field(default=(), max_length=MAX_FIELD_ERRORS)

    @classmethod
    def type_for(cls, code: ErrorCode) -> str:
        return f"{ERROR_TYPE_PREFIX}{code.value}"
